// The simulation runs in Buffers 0 to 3 (see their tabs). This draws its latest step, lit as if
// V were raised up from the surface, in colours that drift as it plays.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 px = iResolution.y / 200. / iResolution.xy;  // One of the simulation's grid cells.
  vec2 uv = fragCoord / iResolution.xy;
  float v = texture(iBuffer3, uv).g;
  vec2 slope = vec2(
    texture(iBuffer3, uv + vec2(px.x, 0.)).g - texture(iBuffer3, uv - vec2(px.x, 0.)).g,
    texture(iBuffer3, uv + vec2(0., px.y)).g - texture(iBuffer3, uv - vec2(0., px.y)).g);
  vec3 normal = normalize(vec3(-3. * slope, 1.));
  vec3 light = normalize(vec3(-0.5, 0.7, 0.6));
  float diffuse = max(dot(normal, light), 0.);
  float shine = pow(max(dot(reflect(-light, normal), vec3(0., 0., 1.)), 0.), 24.);
  float level = smoothstep(0.05, 0.4, v);
  vec3 palette = 0.5 + 0.5 * cos(6.2832 * (0.6 * level + 0.05 * iTime + vec3(0., 0.33, 0.67)));
  vec3 col = mix(vec3(0.02, 0.02, 0.06), palette, level) * (0.35 + 0.85 * diffuse) + 0.6 * shine * level;
  fragColor = vec4(col, 1.);
}

